jsonTools.init:
function init(eli) {
  var STORE = "team_commentary";
  var FACETS = ["agreementType", "clauseId", "sectionKey", "company", "jurisdiction", "counterpartyCountry", "entityType"];
  // Facets nothing extracts yet — a rule using one can't fire, and the UI
  // says so rather than letting it look live.
  var UNRESOLVED = { company: 1, jurisdiction: 1, counterpartyCountry: 1, entityType: 1 };
  var TIERS = [
    { id: "advisory", label: "Advisory", bg: "#f1f5f9", fg: "#64748b", bar: "#94a3b8" },
    { id: "default", label: "Default", bg: "#ccfbf1", fg: "#0f766e", bar: "#0f766e" },
    { id: "strong", label: "Strong", bg: "#ffedd5", fg: "#b45309", bar: "#b45309" },
    { id: "mandatory", label: "Mandatory", bg: "#fee2e2", fg: "#991b1b", bar: "#991b1b" },
  ];
  var OPS = [
    { id: "eq", label: "=", n: 1 }, { id: "ne", label: "≠", n: 1 },
    { id: "in", label: "in", n: 2 }, { id: "nin", label: "not in", n: 2 },
  ];
  // ── Vocabularies. A facet with a known value set gets a dropdown so people
  //    can't fragment it ("University" / "university" / "Uni"). Every list
  //    keeps an "+ Other…" escape so a missing value never blocks anyone —
  //    anything typed is remembered and offered to the next author.
  var VOCAB = {
    entityType: ["company", "university", "individual", "government", "non-profit", "other"],
    agreementType: [],     // filled from the managed `agreement_types` store
    counterpartyCountry: ["US", "GB", "FR", "DE", "IT", "ES", "NL", "PL", "BR", "MX", "CA", "IN", "CN", "JP", "AU", "EU", "EEA"],
    jurisdiction: ["US-NY", "US-DE", "US-CA", "GB-ENG", "FR", "DE", "NL", "SG", "CH"],
  };
  var VOCAB_KEY = "team_guidance.vocabExtras";
  function vocabExtras() {
    try { return JSON.parse(eli.settings.get(VOCAB_KEY) || "{}") || {}; } catch (_) { return {}; }
  }
  function rememberValue(facet, value) {
    var v = String(value || "").trim();
    if (!v || !VOCAB[facet]) return;
    var known = (VOCAB[facet] || []).concat(vocabExtras()[facet] || []);
    for (var i = 0; i < known.length; i++) if (String(known[i]).toLowerCase() === v.toLowerCase()) return;
    var ex = vocabExtras();
    ex[facet] = (ex[facet] || []).concat([v]);
    try { eli.settings.set(VOCAB_KEY, JSON.stringify(ex)); } catch (_) {}
  }
  function vocabFor(facet) {
    if (!VOCAB[facet]) return null;                       // free-text facet
    var extra = vocabExtras()[facet] || [];
    var seen = {}, out = [];
    VOCAB[facet].concat(extra).forEach(function (v) {
      var k = String(v).toLowerCase();
      if (!seen[k]) { seen[k] = 1; out.push(String(v)); }
    });
    return out;
  }
  // Agreement types come from the same managed store Build Draft uses, so
  // this tool never invents a competing list.
  function loadAgreementTypes() {
    return Promise.resolve(eli.storage.getAll("agreement_types")).then(function (r) {
      var list = (Array.isArray(r) ? r : [])
        .filter(function (x) { return x && !x.pseudo; })
        .map(function (x) { return x.label || x.name || x.id; })
        .filter(Boolean);
      if (list.length) VOCAB.agreementType = list;
    }).catch(function () {});
  }

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function canon(s) {
    return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  }
  function genId() { return "tc_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10); }
  function tierOf(r) { return String((r && r.tier) || "default"); }
  function tierMeta(id) {
    for (var i = 0; i < TIERS.length; i++) if (TIERS[i].id === id) return TIERS[i];
    return TIERS[1];
  }
  function fmtDate(iso) {
    try {
      var d = new Date(iso);
      if (isNaN(d.getTime())) return "";
      return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
    } catch (_) { return ""; }
  }
  function identity() {
    var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
    var us = window.userSettings || {};
    return {
      name: (us.name || us.firstName || ident.name || "(unknown)"),
      email: (us.userEmail || ident.email || ""),
      group: (us.userGroup || ident.group || ""),
    };
  }

  function loadAll() {
    return Promise.resolve(eli.storage.getAll(STORE)).then(function (r) { return r || []; })
      .catch(function () { return []; });
  }

  // ── Playbook guidance, read-only ─────────────────────────────────────
  // Schema (per playbook_manager):
  //   { id: <agreementType>, clauseMapping: { libraryName, clauses: [...] } }
  //   clause: { id, sectionId (name), articleId, text, guidanceComment,
  //             lockClause, lockComment, approvalRequired, fallbacks:[{text}] }
  // Flattened into the same card shape as team rows so one library shows
  // everything. These are NEVER written back — the playbook is published
  // through its own pipeline.
  function loadPlaybookRows() {
    return Promise.resolve(eli.storage.getAll("playbooks")).then(function (rows) {
      var out = [];
      (rows || []).forEach(function (p) {
        if (!p || !p.id || String(p.id).charAt(0) === "_") return;
        var cm = (p.clauseMapping && typeof p.clauseMapping === "object") ? p.clauseMapping : p;
        var agType = p.agreementType || p.id;
        var lib = cm.libraryName || p.libraryName || "";
        (Array.isArray(cm.clauses) ? cm.clauses : []).forEach(function (c, i) {
          if (!c) return;
          var name = c.sectionId || c.id || ("Clause " + (i + 1));
          var conds = [{ facet: "agreementType", op: "eq", value: String(agType) },
                       { facet: "clauseId", op: "eq", value: String(name) }];
          var base = {
            _virtual: true, authorName: lib || "Colgate Playbook", authorGroup: agType,
            createdAt: p.updatedAt || p.createdAt || "", updatedAt: p.updatedAt || "",
            agreementType: agType, sectionLabel: name,
            conditions: conds, scope: scopeFromConditions(conds),
            status: "active", origin: "authored", libraryName: lib,
          };
          var g = String(c.guidanceComment || "").trim();
          if (g) out.push(Object.assign({}, base, {
            id: "pb::" + agType + "::" + name + "::g", source: "playbook",
            text: g, tier: c.approvalRequired ? "strong" : "default",
          }));
          if (c.lockClause) out.push(Object.assign({}, base, {
            id: "pb::" + agType + "::" + name + "::lock", source: "lock", tier: "mandatory",
            text: String(c.lockComment || "").trim() ||
              ("This clause is locked. Changes to " + name + " require approval before responding."),
          }));
          (Array.isArray(c.fallbacks) ? c.fallbacks : []).forEach(function (fb, fi) {
            var t = String((fb && (fb.text || fb.body)) || "").trim();
            if (!t) return;
            out.push(Object.assign({}, base, {
              id: "pb::" + agType + "::" + name + "::fb" + fi, source: "fallback", tier: "default",
              text: t, rationale: "Pre-approved fallback position — offer this rather than reverting.",
            }));
          });
        });
      });
      return out;
    }).catch(function () { return []; });
  }
  function put(row) { return Promise.resolve(eli.storage.put(STORE, row)).then(function () { return row; }); }

  // ── Source: who says so. Playbook-derived rows are read-only here.
  function sourceOf(r) {
    var tags = Array.isArray(r.tags) ? r.tags : [];
    if (r.source === "playbook" || tags.indexOf("playbook") >= 0) return "playbook";
    if (r.source === "fallback" || tags.indexOf("fallback") >= 0) return "fallback";
    if (r.source === "lock" || tags.indexOf("lock") >= 0) return "lock";
    if (r.origin === "derived" || tags.indexOf("eli-disagreement") >= 0) return "team";
    return "person";
  }
  function isReadOnly(r) { var s = sourceOf(r); return s === "playbook" || s === "fallback" || s === "lock"; }
  function srcBadge(r) {
    var s = sourceOf(r), st, txt;
    if (s === "playbook") { st = "background:#1e3a8a;color:#fff;border:1px solid #16306e;"; txt = "📕 Colgate Playbook"; }
    else if (s === "fallback") { st = "background:#fffdf6;color:#7c4a03;border:1px solid #c9a227;"; txt = "📗 Playbook fallback"; }
    else if (s === "lock") { st = "background:#450a0a;color:#fecaca;border:1px solid #7f1d1d;"; txt = "🔒 Locked clause"; }
    else if (s === "team") {
      var n = (Array.isArray(r.evidence) ? r.evidence.length : 0);
      st = "background:#0f766e;color:#fff;border:1px solid #0d5c56;";
      txt = "👥 Team" + (n ? " · " + n + " evidence" : "");
    } else { st = "background:#fff;color:#0f766e;border:1px solid #0f766e;"; txt = "👤 " + (r.authorName || "Unknown"); }
    return '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.09em;padding:4px 8px;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;' + st + '">' + esc(txt) + '</span>';
  }

  // ── Conditions. `scope` holds the equality facets the RR matcher honours
  //    today; `conditions` holds the full expression set. A rule whose
  //    conditions can't be expressed as equality is flagged, not silently
  //    treated as live.
  function conditionsOf(r) {
    if (Array.isArray(r.conditions) && r.conditions.length) return r.conditions;
    var out = [], sc = r.scope || {};
    FACETS.forEach(function (f) { if (sc[f]) out.push({ facet: f, op: "eq", value: String(sc[f]) }); });
    if (!out.length && r.sectionId) {
      var p = String(r.sectionId).split("::");
      if (p[0]) out.push({ facet: "agreementType", op: "eq", value: p[0] });
      if (p[1] || p[2]) out.push({ facet: "sectionKey", op: "eq", value: (p[1] || "") + "::" + (p[2] || "") });
    }
    return out;
  }
  function scopeFromConditions(conds) {
    var sc = {};
    FACETS.forEach(function (f) { sc[f] = null; });
    (conds || []).forEach(function (c) { if (c.op === "eq" && c.value) sc[c.facet] = c.value; });
    return sc;
  }
  function blockers(conds) {
    var b = { facts: [], ops: false };
    (conds || []).forEach(function (c) {
      if (UNRESOLVED[c.facet] && b.facts.indexOf(c.facet) < 0) b.facts.push(c.facet);
      if (c.op !== "eq") b.ops = true;
    });
    return b;
  }
  function condChip(c) {
    var op = c.op === "eq" ? "=" : c.op === "ne" ? "≠" : c.op === "in" ? "in" : "not in";
    var warn = UNRESOLVED[c.facet];
    return '<span style="font:700 10.5px Inter,sans-serif;padding:1px 7px;white-space:nowrap;display:inline-block;margin:1px 3px 1px 0;' +
      (warn ? 'background:#fff7ed;border:1px solid #fdba74;color:#9a3412;' : 'background:#f0fdfa;border:1px solid #99f6e4;color:#0f766e;') +
      '">' + esc(c.facet) + ' ' + esc(op) + ' ' + esc(c.value) + '</span>';
  }

  // ─────────────────────────────────────────────────────────────────────
  var overlay = null, rows = [], view = "lib", groupBy = "agreementType", srcFilter = "all", q = "", insOpen = false;
  var insBy = "person";   // Contributors panel: by person (default) or by agreement type
  var draft = null;   // open editor: {row, conds, isNew}

  function visible() {
    var ql = q.toLowerCase().trim();
    return rows.filter(function (r) {
      if (!r || r.status === "archived") return false;
      if (view === "pend") { if (r.status !== "pending") return false; }
      else if (r.status === "pending") return false;
      var s = sourceOf(r);
      if (srcFilter === "playbook" && !(s === "playbook" || s === "fallback" || s === "lock")) return false;
      if (srcFilter === "team" && (s === "playbook" || s === "fallback" || s === "lock")) return false;
      if (ql) {
        var hay = (r.text || "") + " " + (r.rationale || "") + " " + (r.reference || "") + " " + (r.authorName || "") +
          " " + conditionsOf(r).map(function (c) { return c.facet + c.value; }).join(" ");
        if (hay.toLowerCase().indexOf(ql) < 0) return false;
      }
      return true;
    });
  }
  function groupKey(r) {
    if (groupBy === "agreementType") {
      var at = (r.scope && r.scope.agreementType) || r.agreementType || "";
      return at ? String(at).toUpperCase() : "All agreements";
    }
    if (groupBy === "clause") {
      var cl = (r.scope && r.scope.clauseId) || r.sectionLabel || "";
      return cl || "Unmapped";
    }
    if (groupBy === "source") {
      var s = sourceOf(r);
      return s === "person" ? "Written by people" : s === "team" ? "Derived from reviews" : "Colgate playbook";
    }
    return "Recently added";
  }

  function ruleCard(r) {
    var conds = conditionsOf(r), tm = tierMeta(tierOf(r)), ro = isReadOnly(r), bl = blockers(conds);
    var legacy = !r.scope && !r.conditions;
    return '<div data-tg-card="' + esc(r.id) + '" style="background:' + (ro ? "linear-gradient(180deg,#fdfcf7,#fbf9f0)" : "#fff") +
        ';border:1px solid #dbe3ec;border-left:3px solid ' + tm.bar + ';padding:13px 15px;margin-bottom:8px;">' +
      '<div style="display:flex;align-items:flex-start;gap:9px;flex-wrap:wrap;margin-bottom:7px;">' +
        srcBadge(r) +
        '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;padding:3px 7px;background:' + tm.bg + ';color:' + tm.fg + ';white-space:nowrap;">' + esc(tm.label) + '</span>' +
        (legacy ? '<span style="font:700 9px Inter,sans-serif;color:#94a3b8;background:#f8fafc;border:1px solid #e2e8f0;padding:1px 6px;text-transform:uppercase;letter-spacing:.05em;">Legacy · unreviewed</span>' : '') +
        '<span style="font:600 13.5px/1.55 Inter,sans-serif;color:#0f172a;flex:1;min-width:240px;white-space:pre-wrap;">' + esc(r.text || "") + '</span>' +
      '</div>' +
      '<div style="font:500 11px/1.6 Inter,sans-serif;color:#475569;margin-bottom:6px;">' +
        (conds.length ? 'Applies when ' + conds.map(condChip).join("")
          : '<span style="font:700 10.5px Inter,sans-serif;background:#f8fafc;border:1px solid #e2e8f0;color:#94a3b8;padding:1px 7px;">any agreement</span>') +
      '</div>' +
      (r.rationale ? '<div style="font:400 11.5px/1.55 Inter,sans-serif;color:#475569;margin-bottom:7px;">' + esc(r.rationale) +
        (r.reference ? ' <span style="font:600 10.5px Inter,sans-serif;color:#7c4a03;background:#fffdf6;border:1px solid #e6d28a;padding:1px 6px;">' + esc(r.reference) + '</span>' : '') + '</div>' : '') +
      (bl.facts.length || bl.ops
        ? '<div style="font:700 9.5px Inter,sans-serif;color:#9a3412;background:#fff7ed;border:1px solid #fdba74;padding:3px 8px;display:inline-block;margin-bottom:7px;">⚠ Cannot fire yet — ' +
            (bl.facts.length ? esc(bl.facts.join(", ")) + ' not extracted from documents' : '') +
            (bl.facts.length && bl.ops ? ' · ' : '') +
            (bl.ops ? 'non-equality conditions not yet enforced' : '') + '</div>'
        : '') +
      '<div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding-top:7px;border-top:1px solid #f1f5f9;font:500 10px/1.4 Inter,sans-serif;color:#94a3b8;">' +
        (ro ? '<span style="font:600 9.5px Inter,sans-serif;color:#64748b;background:#f1f5f9;border:1px solid #e2e8f0;padding:2px 7px;">🔒 Read-only</span>' : '') +
        '<span><b style="color:#64748b;">' + esc(r.authorName || "Unknown") + '</b>' + (r.authorGroup ? ' · ' + esc(r.authorGroup) : '') + '</span>' +
        '<span>' + esc(fmtDate(r.createdAt)) + '</span>' +
        (r.updatedAt && r.updatedAt !== r.createdAt ? '<span>· edited ' + esc(fmtDate(r.updatedAt)) + '</span>' : '') +
        (typeof r.firedCount === "number" ? '<span>· fired <b style="color:#64748b;">' + r.firedCount + '×</b></span>' : '') +
        '<span style="margin-left:auto;display:flex;gap:6px;">' +
          (ro ? '' : '<button data-tg-edit="' + esc(r.id) + '" style="font:700 9.5px Inter,sans-serif;color:#0f766e;background:#f0fdfa;border:1px solid #99f6e4;padding:3px 9px;cursor:pointer;">Edit</button>') +
          (ro ? '' : '<button data-tg-archive="' + esc(r.id) + '" style="font:700 9.5px Inter,sans-serif;color:#94a3b8;background:#fff;border:1px solid #e2e8f0;padding:3px 9px;cursor:pointer;">Archive</button>') +
        '</span>' +
      '</div>' +
    '</div>';
  }

  function pendCard(r) {
    var conds = conditionsOf(r);
    return '<div style="background:#fff;border:1px solid #dbe3ec;border-left:3px solid #b45309;padding:13px 15px;margin-bottom:8px;">' +
      '<div style="display:flex;align-items:flex-start;gap:9px;flex-wrap:wrap;margin-bottom:7px;">' +
        '<span style="font:800 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;padding:3px 7px;background:#ffedd5;color:#b45309;">Pending</span>' +
        srcBadge(r) +
        '<span style="font:600 13px/1.55 Inter,sans-serif;color:#0f172a;flex:1;min-width:240px;white-space:pre-wrap;">' + esc(r.text || "") + '</span>' +
      '</div>' +
      '<div style="font:500 11px/1.6 Inter,sans-serif;color:#475569;margin-bottom:9px;">' + conds.map(condChip).join("") + '</div>' +
      '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">' +
        '<button data-tg-promote="' + esc(r.id) + '" style="padding:7px 14px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;background:linear-gradient(135deg,#0f766e,#0d5c56);color:#fff;border:1px solid #0d5c56;">✓ Promote to rule</button>' +
        '<button data-tg-edit="' + esc(r.id) + '" style="padding:7px 12px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#475569;border:1px solid #cbd5e1;">Edit first</button>' +
        '<button data-tg-archive="' + esc(r.id) + '" style="padding:7px 12px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#94a3b8;border:1px solid #e2e8f0;">Dismiss</button>' +
        '<span style="margin-left:auto;font:500 10px Inter,sans-serif;color:#94a3b8;font-style:italic;">' + esc(r.authorName || "") + ' · ' + esc(fmtDate(r.createdAt)) + ' · evidence never reaches the model</span>' +
      '</div>' +
    '</div>';
  }

  function insightsHtml() {
    var byPerson = {}, byType = {}, blocked = {}, active = 0, pending = 0;
    rows.forEach(function (r) {
      if (!r || r.status === "archived") return;
      if (r.status === "pending") { pending++; return; }
      active++;
      // People only — a playbook row's "author" is a library, not a person.
      if (!r._virtual) byPerson[r.authorName || "Unknown"] = (byPerson[r.authorName || "Unknown"] || 0) + 1;
      // Coverage counts everything, since that's the useful question.
      var at = (r.scope && r.scope.agreementType) || r.agreementType || "All agreements";
      byType[String(at).toUpperCase()] = (byType[String(at).toUpperCase()] || 0) + 1;
      blockers(conditionsOf(r)).facts.forEach(function (f) { blocked[f] = (blocked[f] || 0) + 1; });
    });
    var src = insBy === "type" ? byType : byPerson;
    var top = Object.keys(src).map(function (k) { return { k: k, n: src[k] }; })
      .sort(function (a, b) { return b.n - a.n; }).slice(0, 8);
    var max = top.length ? top[0].n : 1;
    var bl = Object.keys(blocked).map(function (k) { return { k: k, n: blocked[k] }; }).sort(function (a, b) { return b.n - a.n; });
    var tog = function (id, label) {
      var on = insBy === id;
      return '<button data-tg-insby="' + id + '" style="padding:3px 8px;font:700 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;border:1px solid ' +
        (on ? "#0f766e" : "#1e293b") + ';background:' + (on ? "#0f766e" : "transparent") + ';color:' + (on ? "#fff" : "#64748b") + ';">' + label + '</button>';
    };
    return '<div style="background:#0f172a;color:#cbd5e1;padding:16px 26px;border-bottom:1px solid #1e293b;">' +
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;">' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">' +
            '<span style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#64748b;flex:1;">' +
              (insBy === "type" ? "Coverage by agreement" : "Contributors") + '</span>' +
            tog("person", "Person") + tog("type", "Agreement") +
          '</div>' +
          (top.length ? top.map(function (t) {
            return '<div style="display:flex;gap:8px;font:600 11px/1.7 Inter,sans-serif;"><span style="flex:1;color:#e2e8f0;">' + esc(t.k) + '</span><span style="color:#64748b;">' + t.n + '</span></div>' +
              '<div style="height:5px;background:#0f766e;width:' + Math.round(t.n / max * 100) + '%;"></div>';
          }).join("") : '<div style="font:500 11px Inter,sans-serif;color:#64748b;">' +
              (insBy === "type" ? "Nothing to chart yet." : "No one has written guidance yet — playbook rules aren\'t counted here.") + '</div>') +
        '</div>' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
          '<div style="font:800 9px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#64748b;margin-bottom:8px;">Blocked on fact extraction</div>' +
          (bl.length ? bl.map(function (t) {
            return '<div style="display:flex;gap:8px;font:600 11px/1.7 Inter,sans-serif;"><span style="flex:1;color:#e2e8f0;">' + esc(t.k) + '</span><span style="color:#fbbf24;">' + t.n + ' rule' + (t.n === 1 ? "" : "s") + '</span></div>';
          }).join("") + '<div style="font:500 10px/1.5 Inter,sans-serif;color:#64748b;margin-top:7px;font-style:italic;">Ranked demand — build extraction in this order.</div>'
            : '<div style="font:500 11px Inter,sans-serif;color:#64748b;">Nothing blocked.</div>') +
        '</div>' +
        '<div style="background:#111c33;border:1px solid #1e293b;padding:11px 13px;">' +
